      if (hiCanvaSelectedTarget && hiCanvaSelectedTarget !== target) {
        hiCanvaSelectedTarget.removeAttribute('data-hi-canva-selected');
      }

      hiCanvaSelectedTarget = target;
      target.setAttribute('data-hi-canva-selected', 'true');
